-- Add is_seeded flag to craver_applications
ALTER TABLE craver_applications ADD COLUMN IF NOT EXISTS is_seeded boolean DEFAULT false;
CREATE INDEX IF NOT EXISTS idx_craver_applications_is_seeded ON craver_applications(is_seeded) WHERE is_seeded = true;

