-- Update rejected feeders with background check failure details
UPDATE craver_applications SET background_check = false, reviewer_notes = 'Failed background check - auto-rejected', reviewed_at = created_at + interval '5 days' WHERE is_seeded = true AND status = 'rejected';

-- Update approved feeders with background check passed
UPDATE craver_applications SET background_check = true, background_check_consent = true, reviewed_at = created_at + interval '3 days', reviewer_notes = 'Background check passed - approved' WHERE is_seeded = true AND status = 'approved';